import logging
import traceback
import sys
import os
from on_air_tl_preparation.testline_preparation_resources import get_neighbour_gnbs_and_enbs_info_defaults, \
    power_on_all_pdu_ports, check_vm_and_restart_if_uptime_is_to_long, group_certificates, append_swconfig_flags_if_provided
from on_air_tl_preparation.bts.bts_operations import GnbBtsPreparator
from on_air_tl_preparation.bts.bts_operations import EnbBtsPreparator
from on_air_tl_preparation.log_collector.log_coll_res import GnbLogger
from on_air_tl_preparation.log_collector.log_coll_res import EnbLogger
from taf.rfrl.utilities.logger.custom_logger import log_banner_to_console
from taf.rfrl.utilities.robot.general import get_builtin_value
from taf.rfrl.utilities.robot.decorators import log_as_robot_keyword


def prepare_testline(scfs_path=False,
                     should_LTE_neighbour_be_changed=True,
                     should_5G_neighbour_be_changed=True,
                     swconfig_from_path=False,
                     upload_swconfig_to_neighbour=False,
                     incompatible_error_timer=False,
                     increase_timeout_for_update_sw=False,
                     increase_time_for_checking_bbmod=False,
                     increase_time_for_checking_radios=False,
                     increase_time_for_checking_cells=False,
                     increase_time_for_checking_X2link=False,
                     neighbour_incompatible_error_timer=False,
                     neighbour_increase_timeout_for_update_sw=False,
                     increase_time_for_checking_neighbour_bbmod=False,
                     increase_time_for_checking_neighbour_radios=False,
                     increase_time_for_checking_neighbour_cells=False,
                     scf_prefix_tag=None,
                     wait_for_on_air=True,
                     log_dir=None,
                     wtd_sfp_wa_support=False,
                     bsr_config_file=None,
                     certificates=None,
                     rusw=None,
                     swconfig_flags=None,
                     check_x2_link=True):
    if log_dir is None:
        log_dir = os.path.join(get_builtin_value('OUTPUT DIR'), 'preparation')
    increase_timeout_for_update_sw = int(increase_timeout_for_update_sw) if increase_timeout_for_update_sw else 1800
    neighbour_increase_timeout_for_update_sw = int(neighbour_increase_timeout_for_update_sw) \
        if neighbour_increase_timeout_for_update_sw else 1800
    should_not_print_log_about_success = []

    main_bts, neighbour_enbs, neighbour_gnbs = get_neighbour_gnbs_and_enbs_info_defaults()
    if certificates:
        certificates_gnb, certificates_enb = group_certificates(certificates)
        certificates_gnb_main = certificates_gnb.pop(0)
    else:
        certificates_gnb, certificates_enb, certificates_gnb_main = None, None, None

    power_on_all_pdu_ports()
    swconfig_from_path = append_swconfig_flags_if_provided(source_swconfig_path=swconfig_from_path,
                                                           target_swconfig_path=os.path.join(log_dir, "auto_generated_swconfig.txt"),
                                                           flags=swconfig_flags)
    #enbs
    if should_LTE_neighbour_be_changed:
        prepare_lte_bts_neighbours(increase_time_for_checking_neighbour_bbmod,
                                   increase_time_for_checking_neighbour_cells,
                                   increase_time_for_checking_neighbour_radios, log_dir, neighbour_enbs,
                                   neighbour_incompatible_error_timer, neighbour_increase_timeout_for_update_sw,
                                   scf_prefix_tag, scfs_path, should_not_print_log_about_success, swconfig_from_path,
                                   upload_swconfig_to_neighbour)

    prepare_main_bts(bsr_config_file, incompatible_error_timer, increase_time_for_checking_X2link,
                     increase_time_for_checking_bbmod, increase_time_for_checking_cells,
                     increase_time_for_checking_radios, increase_timeout_for_update_sw, log_dir, main_bts,
                     neighbour_enbs, scf_prefix_tag, scfs_path, should_not_print_log_about_success,
                     swconfig_from_path, wait_for_on_air, wtd_sfp_wa_support, certificates_gnb_main, rusw, check_x2_link)

    #gnbs
    if should_5G_neighbour_be_changed:
        prepare_5g_bts_neighbours(increase_time_for_checking_neighbour_bbmod,
                                  increase_time_for_checking_neighbour_cells,
                                  increase_time_for_checking_neighbour_radios, log_dir, neighbour_gnbs,
                                  neighbour_incompatible_error_timer, neighbour_increase_timeout_for_update_sw,
                                  scf_prefix_tag, scfs_path, should_not_print_log_about_success, swconfig_from_path,
                                  upload_swconfig_to_neighbour, certificates_gnb)

    if not any(should_not_print_log_about_success):
        log_banner_to_console('"Power Stride and Ready to Ride!"\n'
                              '                     *    '
                              'https://www.youtube.com/watch?v=p0wT4uBitcY&ab_channel=Sherif\n'
                              '                     *    Testline prepared for testing')


@log_as_robot_keyword
def prepare_5g_bts_neighbours(increase_time_for_checking_neighbour_bbmod, increase_time_for_checking_neighbour_cells,
                              increase_time_for_checking_neighbour_radios, log_dir, neighbour_gnbs,
                              neighbour_incompatible_error_timer, neighbour_increase_timeout_for_update_sw,
                              scf_prefix_tag,
                              scfs_path, should_not_print_log_about_success, swconfig_from_path,
                              upload_swconfig_to_neighbour, certificates):
    try:
        gnb_log = None
        for gnb_name, gnb_info in neighbour_gnbs.items():
            _log_dir = os.path.join(log_dir, gnb_name)
            certificates = certificates[gnb_info['bts_id']] if certificates else None
            gnb_log = GnbLogger(du_id=gnb_info['du_id'], bts_id=gnb_info['bts_id'], log_dir=_log_dir)
            prepare_5g_bts_neighbour(_log_dir, gnb_info, gnb_log, gnb_name, increase_time_for_checking_neighbour_bbmod,
                                     increase_time_for_checking_neighbour_cells,
                                     increase_time_for_checking_neighbour_radios, neighbour_incompatible_error_timer,
                                     neighbour_increase_timeout_for_update_sw, scf_prefix_tag, scfs_path,
                                     swconfig_from_path, upload_swconfig_to_neighbour, certificates)
    except Exception as err:
        exc_info = sys.exc_info()
        traceback.print_exception(*exc_info)
        log_banner_to_console('Preparing neighbour GNB(s) failed !')
        if gnb_log:
            gnb_log.collect_snapshots()
        should_not_print_log_about_success.append(True)
        del exc_info
        raise PreparingGNBNeighbourError(err)
    finally:
        if gnb_log:
            gnb_log.stop_collecting_bts_log_and_get_it()


@log_as_robot_keyword
def prepare_5g_bts_neighbour(_log_dir, gnb_info, gnb_log, gnb_name, increase_time_for_checking_neighbour_bbmod,
                             increase_time_for_checking_neighbour_cells, increase_time_for_checking_neighbour_radios,
                             neighbour_incompatible_error_timer, neighbour_increase_timeout_for_update_sw,
                             scf_prefix_tag, scfs_path, swconfig_from_path, upload_swconfig_to_neighbour, certificates):
    log_banner_to_console(f'Prepare {gnb_info["bts_type"]} Neighbour Station: {gnb_name}')
    check_vm_and_restart_if_uptime_is_to_long(du_id=gnb_info['du_id'],
                                              bts_id=gnb_info['bts_id'],
                                              bts_type=gnb_info['bts_type'])
    gnb_log.start_collecting_bts_log()
    gnb_bts = GnbBtsPreparator(du_id=gnb_info['du_id'], bts_id=gnb_info['bts_id'], log_dir=_log_dir)
    gnb_bts.prepare_bts_neighbour(neighbour_name=gnb_name,
                                  neighbour_info=gnb_info,
                                  scf_path=scfs_path,
                                  sw_conf_path=swconfig_from_path,
                                  upload_sw_config=upload_swconfig_to_neighbour,
                                  neighbour_incompatible_error_timer=neighbour_incompatible_error_timer,
                                  neighbour_increase_timeout_for_update_sw=
                                  neighbour_increase_timeout_for_update_sw,
                                  increase_time_for_checking_neighbour_bbmod=
                                  increase_time_for_checking_neighbour_bbmod,
                                  increase_time_for_checking_neighbour_radios=
                                  increase_time_for_checking_neighbour_radios,
                                  increase_time_for_checking_neighbour_cells=
                                  increase_time_for_checking_neighbour_cells,
                                  scf_prefix_tag=scf_prefix_tag,
                                  certificates=certificates
                                  )


@log_as_robot_keyword
def prepare_lte_bts_neighbours(increase_time_for_checking_neighbour_bbmod, increase_time_for_checking_neighbour_cells,
                               increase_time_for_checking_neighbour_radios, log_dir, neighbour_enbs,
                               neighbour_incompatible_error_timer, neighbour_increase_timeout_for_update_sw,
                               scf_prefix_tag, scfs_path, should_not_print_log_about_success, swconfig_from_path,
                               upload_swconfig_to_neighbour):
    try:
        for enb_name, enb_info in neighbour_enbs.items():
            _log_dir = os.path.join(log_dir, enb_name)
            enb_log = EnbLogger(du_id=enb_info['du_id'], bts_id=enb_info['bts_id'], log_dir=_log_dir)
            prepare_lte_bts_neighbour(_log_dir, enb_info, enb_log, enb_name, increase_time_for_checking_neighbour_bbmod,
                                      increase_time_for_checking_neighbour_cells,
                                      increase_time_for_checking_neighbour_radios, neighbour_incompatible_error_timer,
                                      neighbour_increase_timeout_for_update_sw, scf_prefix_tag, scfs_path,
                                      swconfig_from_path, upload_swconfig_to_neighbour)
    except Exception as err:
        exc_info = sys.exc_info()
        traceback.print_exception(*exc_info)
        log_banner_to_console('Preparing neighbour ENB(s) failed !')
        enb_log.collect_snapshots()
        should_not_print_log_about_success.append(True)
        del exc_info
        raise PreparingENBNeighbourError(err)
    finally:
        enb_log.stop_collecting_bts_log_and_get_it()


@log_as_robot_keyword
def prepare_lte_bts_neighbour(_log_dir, enb_info, enb_log, enb_name, increase_time_for_checking_neighbour_bbmod,
                              increase_time_for_checking_neighbour_cells, increase_time_for_checking_neighbour_radios,
                              neighbour_incompatible_error_timer, neighbour_increase_timeout_for_update_sw,
                              scf_prefix_tag, scfs_path, swconfig_from_path, upload_swconfig_to_neighbour):
    log_banner_to_console(f'Prepare {enb_info["bts_type"]} Neighbour Station: {enb_name}')
    check_vm_and_restart_if_uptime_is_to_long(du_id=enb_info['du_id'],
                                              bts_id=enb_info['bts_id'],
                                              bts_type=enb_info['bts_type'])
    enb_log.start_collecting_bts_log()
    enb_bts = EnbBtsPreparator(du_id=enb_info['du_id'], bts_id=enb_info['bts_id'], log_dir=_log_dir)
    enb_bts.prepare_bts_neighbour(neighbour_name=enb_name,
                                  neighbour_info=enb_info,
                                  scf_path=scfs_path,
                                  sw_conf_path=swconfig_from_path,
                                  upload_sw_config=upload_swconfig_to_neighbour,
                                  neighbour_incompatible_error_timer=neighbour_incompatible_error_timer,
                                  neighbour_increase_timeout_for_update_sw=
                                  neighbour_increase_timeout_for_update_sw,
                                  increase_time_for_checking_neighbour_bbmod=
                                  increase_time_for_checking_neighbour_bbmod,
                                  increase_time_for_checking_neighbour_radios=
                                  increase_time_for_checking_neighbour_radios,
                                  increase_time_for_checking_neighbour_cells=
                                  increase_time_for_checking_neighbour_cells,
                                  scf_prefix_tag=scf_prefix_tag
                                  )


@log_as_robot_keyword
def prepare_main_bts(bsr_config_file, incompatible_error_timer, increase_time_for_checking_X2link,
                     increase_time_for_checking_bbmod, increase_time_for_checking_cells,
                     increase_time_for_checking_radios, increase_timeout_for_update_sw, log_dir, main_bts,
                     neighbour_enbs, scf_prefix_tag, scfs_path, should_not_print_log_about_success,
                     swconfig_from_path, wait_for_on_air, wtd_sfp_wa_support, certificates, rusw, check_x2_link):
    try:
        if len(main_bts) == 1:
            bts_name = list(main_bts.keys())[0]
            main_bts_info = main_bts[next(iter(main_bts))]
            _log_dir = os.path.join(log_dir, bts_name)
            if main_bts_info['bts_type'] == 'GNB':
                main_bts_obj = GnbBtsPreparator(du_id=main_bts_info['du_id'], bts_id=main_bts_info['bts_id'],
                                                log_dir=_log_dir)
                main_bts_log = GnbLogger(du_id=main_bts_info['du_id'], bts_id=main_bts_info['bts_id'],
                                         log_dir=_log_dir)
            elif main_bts_info['bts_type'] == 'ENB':
                main_bts_obj = EnbBtsPreparator(du_id=main_bts_info['du_id'], bts_id=main_bts_info['bts_id'],
                                                log_dir=_log_dir)
                main_bts_log = EnbLogger(du_id=main_bts_info['du_id'], bts_id=main_bts_info['bts_id'],
                                         log_dir=_log_dir)
            log_banner_to_console(f'Prepare Main ({main_bts_info["bts_type"]}) Station')
            main_bts_log.start_collecting_bts_log()
            main_bts_obj.prepare_main_bts(scf_path=scfs_path,
                                          sw_conf_path=swconfig_from_path,
                                          main_bts=main_bts,
                                          enbs=neighbour_enbs,
                                          incompatible_error_timer=incompatible_error_timer,
                                          increase_timeout_for_update_sw=increase_timeout_for_update_sw,
                                          increase_time_for_checking_bbmod=increase_time_for_checking_bbmod,
                                          increase_time_for_checking_radios=increase_time_for_checking_radios,
                                          increase_time_for_checking_cells=increase_time_for_checking_cells,
                                          increase_time_for_checking_X2link=increase_time_for_checking_X2link,
                                          scf_prefix_tag=scf_prefix_tag,
                                          wait_for_on_air=wait_for_on_air,
                                          wtd_sfp_wa_support=wtd_sfp_wa_support,
                                          bsr_config_file=bsr_config_file,
                                          certificates=certificates,
                                          rusw=rusw,
                                          check_x2_link=check_x2_link)
    except Exception as err:
        exc_info = sys.exc_info()
        traceback.print_exception(*exc_info)
        log_banner_to_console('Preparing Main BTS failed !')
        main_bts_log.collect_snapshots()
        should_not_print_log_about_success.append(True)
        del exc_info
        raise PreparingMainBTSError(err)
    finally:
        main_bts_log.stop_collecting_bts_log_and_get_it()


class PreparingENBNeighbourError(Exception):
    pass


class PreparingGNBNeighbourError(Exception):
    pass


class PreparingMainBTSError(Exception):
    pass
